import os

logdir = "loglar"
# Tüm .log dosyalarını bul (döndürülmüş .log.1 hariç)
log_files = []
for root, dirs, files in os.walk(logdir):
    for f in files:
        if f.endswith('.log') and not f.endswith('.log.1'):
            # f.endswith('.log') zaten .log.1'i elemaz (bittiği .log ile bitmiyor aslında)
            # .log.1 de .log ile bittiği için dikkatli ol:
            pass

# Daha doğru filtreleme: extension'ı tam .log olanlar
log_files = []
for root, dirs, files in os.walk(logdir):
    for f in files:
        if f.endswith('.log') and f != '' and not f.startswith('.'):
            full = os.path.join(root, f)
            log_files.append(full)

print("Bulunan .log dosyaları:")
for lf in sorted(log_files):
    print(f"  {lf}")
    # İçeriği oku ve satırları say
    with open(lf, 'r', encoding='utf-8', errors='replace') as fh:
        lines = fh.readlines()
    counts = {'ERROR': 0, 'WARN': 0, 'INFO': 0}
    for line in lines:
        parts = line.split()
        if len(parts) >= 3:
            level = parts[2]  # 3. alan (0-index'de 2)
            if level in counts:
                counts[level] += 1
    print(f"  {counts}")
    # Ayrıca örnek ilk satır:
    if lines:
        print(f"  İlk satır: {lines[0].strip()[:80]}")
    print()

